  const [isCollapsed, setIsCollapsed] = useState(false);

  // Update filter type and apply changes immediately
  const handleFilterTypeChange = (type: 'single' | 'range') => {
    setYearFilter({
      type,
      minYear: yearFilter.minYear,
      maxYear: yearFilter.maxYear
