            {showYearFilter && (
              <div className="flex flex-col gap-2">
                <div className="flex w-full rounded-lg overflow-hidden bg-white/30 dark:bg-black/20 font-semibold">
                  <button
                    className={`flex-1 p-0.5 transition-colors ${yearFilter.type === 'range' ? 'bg-white/30 dark:bg-black/20' : 'hover:bg-white/20 dark:hover:bg-black/10'}`}
                    onClick={() => handleFilterTypeChange('range')}
                  >
                    Range
                  </button>
                  <button
                    className={`flex-1 p-0.5 transition-colors ${yearFilter.type === 'single' ? 'bg-white/30 dark:bg-black/20' : 'hover:bg-white/20 dark:hover:bg-black/10'}`}
                    onClick={() => handleFilterTypeChange('single')}
                  >
                    Year
                  </button>
                </div>

                {yearFilter.type === 'single' ? (
                  <div className="flex flex-col gap-1 self-end">
                    <label htmlFor="year" className='hidden'>Year</label>
                    <input
                      type="number"
                      id="year"
                      value={yearFilter.minYear}
                      onChange={(e) => setYearFilter({
                        type: 'single',
                        minYear: Number(e.target.value),
                        maxYear: Number(e.target.value)
                      })}
                      className="w-20 px-2 py-0.5 rounded-md border-0 ring-primary bg-white/60 dark:bg-black/20"
                    />
                  </div>
                ) : (
                  <div className="flex flex-row justify-between gap-1">
                    <div className="flex flex-col gap-1">
                      <label htmlFor="minYear" className='hidden'>Min</label>
                      <input
                        type="number"
                        id="minYear"
                        value={yearFilter.minYear}
                        onChange={(e) => setYearFilter({
                          type: 'range',
                          minYear: Number(e.target.value),
                          maxYear: yearFilter.maxYear
                        })}
                        className="w-20 px-2 py-0.5 rounded-md bg-white/60 dark:bg-black/20 border-0 ring-primary"
                      />
                    </div>
                    <div className="flex flex-col gap-1">
                      <label htmlFor="maxYear" className='hidden'>Max</label>
                      <input
                        type="number"
                        id="maxYear"
                        value={yearFilter.maxYear}
                        onChange={(e) => setYearFilter({
                          type: 'range',
                          minYear: yearFilter.minYear,
                          maxYear: Number(e.target.value)
                        })}
                        className="w-20 px-2 py-0.5 rounded-md bg-white/60 dark:bg-black/20 border-0 ring-primary"
                      />
                    </div>
                  </div>
                )}
              </div>
            )}

            {selectedPoint && (
              <div className="flex flex-col gap-2 border-t pt-4 mt-2">
                <h3 className="font-semibold">Selected Point</h3>
                <div className="text-sm">
                  <p>Lat: {selectedPoint.lat.toFixed(4)}°</p>
                  <p>Lng: {selectedPoint.lng.toFixed(4)}°</p>
                </div>
                <button
                  onClick={toggleSimulation}
                  className={`px-3 py-1.5 rounded-md transition-colors ${
                    isSimulating 
                      ? 'bg-red-500 hover:bg-red-600 text-white' 
                      : 'bg-blue-500 hover:bg-blue-600 text-white'
                  }`}
                >
                  {isSimulating ? 'Stop Simulation' : 'Start Simulation'}
                </button>
              </div>
            )}
          </div>
        </>
      )}
    </div>
  );
}

'use client';

import { useCallback, useEffect, useRef, useState } from 'react';
import mapboxgl from 'mapbox-gl';
import 'mapbox-gl/dist/mapbox-gl.css';
import { useData } from '@/contexts/DataContext';

const formatDate = (dateString: string) => {
  return new Date(dateString).toLocaleDateString('en-US', {
    year: 'numeric',
    month: 'long',
    day: 'numeric'
  });
};

const formatMicroplasticsPopup = (properties: GeoJSON.GeoJsonProperties) => {
  if (!properties) return '';

  const relevantData = {
    'Method': properties.SAMPMETHOD,
    'Density': properties.DENSTEXT,
    'Unit': properties.UNIT,
    'Organization': properties.ORG,
    'Date': formatDate(properties.Date),
    'Reference': properties.SHORTREF,
    'DOI': properties.DOI
  };

  return Object.entries(relevantData)
    .map(([key, value]) => value ?
      `
    <p class="flex flex-wrap mb-1 break-all space-x-1">
      <span class="font-semibold">${key}:</span> ${value}
    <p>
    ` : '')
    .join('');
};

const formatNasaPopup = (properties: GeoJSON.GeoJsonProperties) => {
  if (!properties) return '';

  return `
    <p class="flex flex-wrap mb-1 break-all space-x-1">
      <span class="font-semibold">Detection:</span> Floating Marine Debris
    </p>
  `;
};

const formatNtuaPopup = (properties: GeoJSON.GeoJsonProperties) => {
  if (!properties) return '';

  return `
    <p class="flex flex-wrap mb-1 break-all space-x-1">
      <span class="font-semibold">Detection:</span> Marine Floating Debris
    </p>
  `;
};

const calculatePolygonCentroid = (coordinates: number[][][]) => {
  let totalX = 0;
  let totalY = 0;
  let pointCount = 0;

  // Handle the outer ring of the polygon
  coordinates[0].forEach(point => {
    totalX += point[0];
    totalY += point[1];
    pointCount++;
  });

  return [totalX / pointCount, totalY / pointCount];
};

const createPointFeatureFromPolygon = (feature: GeoJSON.Feature): GeoJSON.Feature => {
  const geometry = feature.geometry as GeoJSON.Polygon | GeoJSON.MultiPolygon;
  let centroid;

  if (geometry.type === 'Polygon') {
    centroid = calculatePolygonCentroid(geometry.coordinates);
  } else {
    // For MultiPolygon, use the centroid of the first polygon
    centroid = calculatePolygonCentroid(geometry.coordinates[0]);
  }

  return {
    type: 'Feature',
    geometry: {
      type: 'Point',
      coordinates: centroid
    },
    properties: feature.properties
  };
};

class ParticleSimulation {
  private currentPos: [number, number];
  private path: [number, number][];
  private animationFrameId: number | null = null;
  private map: mapboxgl.Map;
  private sourceId: string;
  private layerId: string;

  constructor(map: mapboxgl.Map, startPos: [number, number]) {
    this.map = map;
    this.currentPos = startPos;
    this.path = [startPos];
    this.sourceId = 'simulation-path';
    this.layerId = 'simulation-path-layer';
    this.setupLayer();
  }

  private setupLayer() {
    if (this.map.getSource(this.sourceId)) {
      this.map.removeLayer(this.layerId);
      this.map.removeSource(this.sourceId);
    }

    this.map.addSource(this.sourceId, {
      type: 'geojson',
      data: {
        type: 'Feature',
        properties: {},
        geometry: {
          type: 'LineString',
          coordinates: this.path
        }
      }
    });

    this.map.addLayer({
      id: this.layerId,
      type: 'line',
      source: this.sourceId,
      paint: {
        'line-color': '#FF9800',
        'line-width': 2,
        'line-opacity': 0.8
      }
    });
  }

  private updatePath() {
    if (!this.map.getSource(this.sourceId)) return;

    (this.map.getSource(this.sourceId) as mapboxgl.GeoJSONSource).setData({
      type: 'Feature',
      properties: {},
      geometry: {
        type: 'LineString',
        coordinates: this.path
      }
    });
  }

  private calculateNextPosition(): [number, number] {
    // Simple ocean current simulation
    const dt = 0.1; // time step

    // Add some randomness to simulate currents
    const randomFactor = 0.02;
    const dx = (Math.random() - 0.5) * randomFactor;
    const dy = (Math.random() - 0.5) * randomFactor;

    // Add a general eastward drift (simulating ocean gyres)
    const eastwardDrift = 0.01;

    // Calculate new position
    let [lon, lat] = this.currentPos;
    lon += (dx + eastwardDrift) * dt;
    lat += dy * dt;

    // Wrap around longitude
    lon = ((lon + 180) % 360) - 180;
    // Clip latitude
    lat = Math.max(-85, Math.min(85, lat));

    return [lon, lat];
  }

  private simulate = () => {
    this.currentPos = this.calculateNextPosition();
    this.path.push(this.currentPos);
    this.updatePath();
    this.animationFrameId = requestAnimationFrame(this.simulate);
  }

  public start() {
    if (!this.animationFrameId) {
      this.simulate();
    }
  }

  public stop() {
    if (this.animationFrameId) {
      cancelAnimationFrame(this.animationFrameId);
      this.animationFrameId = null;
    }
  }

  public cleanup() {
    this.stop();
    if (this.map.getLayer(this.layerId)) {
      this.map.removeLayer(this.layerId);
    }
    if (this.map.getSource(this.sourceId)) {
      this.map.removeSource(this.sourceId);
    }
  }
}

export default function Map() {
  const mapContainerRef = useRef<HTMLDivElement>(null);
  const mapRef = useRef<mapboxgl.Map | null>(null);
  const layersRef = useRef<Set<string>>(new Set());
  const [isStreetView, setIsStreetView] = useState(true);
  const { layers, getFilteredData, dataPointCount, setSelectedPoint } = useData();
  const simulationRef = useRef<ParticleSimulation | null>(null);
  const { selectedPoint, isSimulating } = useData();

  const updateLayer = useCallback((layer: { id: string, color: string, visible: boolean }) => {
    if (!mapRef.current) return;

    const layerId = `${layer.id}-layer`;
    const pointLayerId = `${layerId}-point`;  // Define pointLayerId here
    const map = mapRef.current;
    const data = getFilteredData(layer.id);

    // Remove existing layers and sources
    [layerId, `${layerId}-point`].forEach(id => {
      if (layersRef.current.has(id) && map.getLayer(id)) {
        map.removeLayer(id);
        layersRef.current.delete(id);
      }
    });

    if (map.getSource(layer.id)) {
      map.removeSource(layer.id);
    }
    if (map.getSource(`${layer.id}-point`)) {
      map.removeSource(`${layer.id}-point`);
    }

    // Add click handler for map background first (so it's at the bottom of the stack)
    map.on('click', (e) => {
      // Only clear if we didn't click on a feature
      if (!e.defaultPrevented) {
        setSelectedPoint(null);
      }
    });

    // Add layer if it's meant to be visible
    if (layer.visible) {
      const firstFeature = data.features[0];
      const isPolygon = firstFeature?.geometry.type === 'Polygon' || firstFeature?.geometry.type === 'MultiPolygon';

      if (isPolygon && layer.id !== 'microplastics') {
        // Add the original polygon source
        map.addSource(layer.id, {
          type: 'geojson',
          data: data
        });

        // Create a point source from polygon centroids only for NASA and NTUA data
        const pointData: GeoJSON.FeatureCollection = {
          type: 'FeatureCollection',
          features: data.features.map(createPointFeatureFromPolygon)
        };

        map.addSource(`${layer.id}-point`, {
          type: 'geojson',
          data: pointData
        });

        // Add point layer for all zoom levels (but fade out at high zoom)
        const pointLayer: mapboxgl.LayerSpecification = {
          id: pointLayerId,
          type: 'circle',
          source: `${layer.id}-point`,
          paint: {
            'circle-radius': [
              'interpolate',
              ['linear'],
              ['zoom'],
              0, 6,
              8, 4
            ],
            'circle-color': layer.color,
            'circle-opacity': [
              'interpolate',
              ['linear'],
              ['zoom'],
              9, 0.6,  // Full opacity until zoom level 9
              11, 0    // Fade to completely transparent by zoom level 12
            ],
            'circle-stroke-width': 1,
            'circle-stroke-color': '#ffffff',
            'circle-stroke-opacity': [
              'interpolate',
              ['linear'],
              ['zoom'],
              9, 1,
              11, 0
            ]
          }
        };
        map.addLayer(pointLayer);
        layersRef.current.add(pointLayerId);

        // Add polygon layer that fades in at higher zoom levels
        const polygonLayer: mapboxgl.LayerSpecification = {
          id: layerId,
          type: 'fill',
          source: layer.id,
          paint: {
            'fill-color': layer.color,
            'fill-opacity': [
              'interpolate',
              ['linear'],
              ['zoom'],
              9, 0,    // Completely transparent until zoom level 9
              11, 0.6  // Fade to full opacity by zoom level 12
            ],
            'fill-outline-color': '#ffffff'
          }
        };
        map.addLayer(polygonLayer);
        layersRef.current.add(layerId);

        // Add click handlers for both polygon and point layers
        [pointLayerId, layerId].forEach(id => {
          map.on('click', id, (e) => {
            e.preventDefault(); // Prevent event bubbling
            const feature = e.features?.[0];
            if (!feature) return;

            const coordinates = e.lngLat;
            const properties = feature.properties;

            setSelectedPoint({
              lat: coordinates.lat,
              lng: coordinates.lng,
              properties: properties,
              layerId: layer.id
            });

            const popupContent = layer.id === 'microplastics'
              ? formatMicroplasticsPopup(properties)
              : layer.id === 'nasa'
                ? formatNasaPopup(properties)
                : formatNtuaPopup(properties);

            new mapboxgl.Popup()
              .setLngLat(coordinates)
              .setHTML(`
                <div class="flex flex-col text-deep-water p-2 max-w-sm">
                  <div class="mb-3">
                    <div class="mb-1">
                      <span class="font-semibold">Latitude:</span> ${coordinates.lat.toFixed(4)}°
                    </div>
                    <div class="mb-1">
                      <span class="font-semibold">Longitude:</span> ${coordinates.lng.toFixed(4)}°
                    </div>
                  </div>
                  <div class="flex flex-col space-y-0.5">
                    ${popupContent}
                  </div>
                  ${properties?.DOI ? `
                    <button class="mt-2 text-sm">
                      <a href="${properties.DOI}" 
                         target="_blank" 
                         rel="noopener noreferrer"
                         class="text-blue-600 hover:text-blue-800 hover:underline">
                        View Research Paper
                      </a>
                    </button>
                  ` : ''}
                </div>
              `)
              .addTo(map);
          });

          map.on('mouseenter', id, () => {
            map.getCanvas().style.cursor = 'pointer';
          });

          map.on('mouseleave', id, () => {
            map.getCanvas().style.cursor = '';
          });
        });
      } else {
        // For non-polygon data or microplastics, use regular circle layer
        map.addSource(layer.id, {
          type: 'geojson',
          data: data
        });

        const layerConfig: mapboxgl.LayerSpecification = {
          id: layerId,
          type: 'circle',
          source: layer.id,
          paint: {
            'circle-radius': [
              'interpolate',
              ['linear'],
              ['zoom'],
              0, 4,
              8, 6
            ],
            'circle-color': layer.color,
            'circle-opacity': 0.6,
            'circle-stroke-width': 1,
            'circle-stroke-color': '#ffffff',
            'circle-stroke-opacity': 1
          }
        };

        map.addLayer(layerConfig);
        layersRef.current.add(layerId);

        // Add click handler for regular point layer
        map.on('click', layerId, (e) => {
          e.preventDefault(); // Prevent event bubbling
          const feature = e.features?.[0];
          if (!feature) return;

          const coordinates = e.lngLat;
          const properties = feature.properties;

          setSelectedPoint({
            lat: coordinates.lat,
            lng: coordinates.lng,
            properties: properties,
            layerId: layer.id
          });

          const popupContent = layer.id === 'microplastics'
            ? formatMicroplasticsPopup(properties)
            : layer.id === 'nasa'
              ? formatNasaPopup(properties)
              : formatNtuaPopup(properties);

          new mapboxgl.Popup()
            .setLngLat(coordinates)
            .setHTML(`
              <div class="flex flex-col text-deep-water p-2 max-w-sm">
                <div class="mb-3">
                  <div class="mb-1">
                    <span class="font-semibold">Latitude:</span> ${coordinates.lat.toFixed(4)}°
                  </div>
                  <div class="mb-1">
                    <span class="font-semibold">Longitude:</span> ${coordinates.lng.toFixed(4)}°
                  </div>
                </div>
                <div class="flex flex-col space-y-0.5">
                  ${popupContent}
                </div>
                ${properties?.DOI ? `
                  <button class="mt-2 text-sm">
                    <a href="${properties.DOI}" 
                       target="_blank" 
                       rel="noopener noreferrer"
                       class="text-blue-600 hover:text-blue-800 hover:underline">
                      View Research Paper
                    </a>
                  </button>
                ` : ''}
              </div>
            `)
            .addTo(map);
        });

        map.on('mouseenter', layerId, () => {
          map.getCanvas().style.cursor = 'pointer';
        });

        map.on('mouseleave', layerId, () => {
          map.getCanvas().style.cursor = '';
        });
      }
    }
  }, [getFilteredData, setSelectedPoint]);

  const loadMap = useCallback(() => {
    // Only initialize map if it hasn't been initialized yet
    if (!mapRef.current && mapContainerRef.current) {
      mapboxgl.accessToken = process.env.NEXT_PUBLIC_MAPBOX_TOKEN;

      mapRef.current = new mapboxgl.Map({
        container: mapContainerRef.current,
        style: 'mapbox://styles/mapbox/streets-v12',
        center: [-105.272148, 40.047050],
        zoom: 2
      });

      mapRef.current.on('load', () => {
        layers.forEach(updateLayer);
      });
    }
  }, [layers, updateLayer]);

  // Initialize map only once
  useEffect(() => {
    loadMap();
  }, [loadMap]); // Empty dependency array since we only want to initialize once

  // Update layers when they change
  useEffect(() => {
    if (mapRef.current?.loaded()) {
      layers.forEach(updateLayer);
    }
  }, [layers, updateLayer]);

  const toggleMapStyle = useCallback(() => {
    const satellite = 'mapbox://styles/mapbox/satellite-v9';
    const streets = 'mapbox://styles/mapbox/streets-v12';

    if (mapRef.current) {
      mapRef.current.setStyle(isStreetView ? satellite : streets);
      setIsStreetView(!isStreetView);

      // Re-add data layers after style change
      mapRef.current.once('style.load', () => {
        layers.forEach(updateLayer);
      });
    }
  }, [isStreetView, layers, updateLayer]);

  // Add simulation effect
  useEffect(() => {
    if (!mapRef.current || !selectedPoint) return;

    // Cleanup previous simulation
    if (simulationRef.current) {
      simulationRef.current.cleanup();
      simulationRef.current = null;
    }

    // Create new simulation if point is selected
    simulationRef.current = new ParticleSimulation(
      mapRef.current,
      [selectedPoint.lng, selectedPoint.lat]
    );

    if (isSimulating) {
      simulationRef.current.start();
    }

    return () => {
      simulationRef.current?.cleanup();
    };
  }, [selectedPoint, isSimulating]);

  // Handle simulation state changes
  useEffect(() => {
    if (!simulationRef.current) return;

    if (isSimulating) {
      simulationRef.current.start();
    } else {
      simulationRef.current.stop();
    }
  }, [isSimulating]);

  return (
    <div className="relative w-full h-full">
      <div ref={mapContainerRef} className="w-full h-full" />

      <div className="absolute top-16 right-4 flex flex-col gap-2 bg-white/30 dark:bg-black/40 backdrop-blur-md px-4 py-2 rounded-md shadow-md">
        {layers.map(layer => layer.visible && (
          <p key={layer.id} className="font-medium text-foreground flex items-center gap-2">
            <span className="w-3 h-3 inline-block rounded-full" style={{ backgroundColor: layer.color }}></span>
            {dataPointCount[layer.id]} points
          </p>
        ))}
      </div>

      <button
        onClick={toggleMapStyle}
        className="group absolute bottom-4 right-4 ml-auto bg-white/30 dark:bg-black/40 backdrop-blur-md p-2 rounded-md shadow-md hover:bg-deep-water transition-colors text-2xl"
      >
        <span className="transition-opacity duration-200 group-hover:opacity-0">
          {isStreetView ? '🚦' : '🛰️'}
        </span>
        <span className="absolute top-1/2 left-1/2 -translate-x-1/2 -translate-y-1/2 opacity-0 transition-opacity duration-200 group-hover:opacity-100">
          {isStreetView ? '🛰️' : '🚦'}
        </span>
      </button>
    </div>
  );
}

